{
  "failure_mode": "collision",
  "evidence": [
    "c5t12_s1952301689: collision at t=9.717 while robot moving 0.08 m/s; first unmapped point detected at t=4.73 at 1.0 m, bearing -21°, DWA active only until t≈5.03 (0.3 s window) → no avoidance.",
    "c5t12_s2000876769: collision at t=51.7 while robot stopped; unmapped point entered 2 m range at t=48.35 (bearing -48°) but DWA deactivated after short debounce, so robot remained stationary and was hit.",
    "c5t12_s471324936: stall abort at t=99.48 after 99 s with only 0.295 m movement; gap to tracked movers stayed > _SAFE_DIST and unmapped points never triggered DWA, leaving robot idle."
  ],
  "assumptions": [
    {
      "assumption": "Moving objects will be clustered into tracks (M) and used for avoidance",
      "holds": false,
      "why": "In collisions (runs 1,2) the mover was not reliably tracked, so DWA never considered it."
    },
    {
      "assumption": "A 0.3 s DWA activation window is sufficient to plan safe motion until the threat passes",
      "holds": false,
      "why": "Collisions occurred many seconds after the window closed, showing the window is too short."
    },
    {
      "assumption": "Margin base 0.15 m plus robot/mover radii provides enough safety buffer",
      "holds": false,
      "why": "Collision at 0.56 m lateral offset indicates the margin was insufficient for fast‑approaching objects."
    },
    {
      "assumption": "Unmapped raw points filtered by _unmapped_raw correctly represent moving objects",
      "holds": true,
      "why": "first_not_on_map timestamps show unmapped points were seen early, but they were not used persistently."
    },
    {
      "assumption": "Robot can resume normal waypoint following after a brief pause without re‑evaluating threats",
      "holds": false,
      "why": "Threats persisted after pause, leading to collisions and stalls."
    }
  ],
  "approach_families": [
    { "family": "baseline (no control)", "turns": "0", "result": "0/1 pass" },
    { "family": "simple pause based on unmapped points", "turns": "1,2", "result": "5/9 passes" },
    { "family": "gap‑based detour", "turns": "3", "result": "0/3 passes" },
    { "family": "predictive speed scaling", "turns": "4", "result": "2/5 passes" },
    { "family": "velocity‑obstacle planner", "turns": "5,6,7,8", "result": "8/14 passes" },
    { "family": "3D‑lidar integration (with VO)", "turns": "6", "result": "3/6 passes" },
    { "family": "TTC binary stop / early stop", "turns": "7,8,9,10", "result": "0/12 passes" },
    { "family": "potential‑field avoidance", "turns": "11", "result": "4/7 passes" },
    { "family": "dynamic‑window (DWA) short‑window", "turns": "12", "result": "2/5 passes" }
  ],
  "candidates": [
    {
      "idea": "Make DWA persistent: reset st[\"dwa_until\"] each step while any unmapped point is within _PF_RANGE, so DWA runs continuously until the threat clears.",
      "new_family": true,
      "for": "Collisions where the short DWA window missed later approach of the same object.",
      "risk": "Higher CPU load; may cause oscillations if DWA keeps switching commands."
    },
    {
      "idea": "Replace DWA with a Vector‑Field‑Histogram (VFH) reactive planner that builds a polar histogram from unmapped lidar points each cycle, selects the widest gap > robot width, and steers toward the goal through that gap.",
      "new_family": true,
      "for": "Robust gap detection without relying on tracking; handles sudden appearance of moving boxes.",
      "risk": "May become overly conservative in cluttered aisles, causing stalls if no gap meets the width threshold."
    },
    {
      "idea": "Hybrid approach: use the existing potential‑field to compute a desired heading, then feed that heading into a simplified DWA that only varies speed, keeping the heading fixed for the horizon.",
      "new_family": false,
      "for": "Leverages successful PF heading while preserving DWA speed optimization.",
      "risk": "Complex interaction between PF and DWA could produce conflicting commands and instability."
    }
  ],
  "chosen": "VFH reactive planner was selected because it directly addresses the missed gap detection that caused collisions and does not depend on fragile tracking or short‑window activation.",
  "target": "controller logic and addition of VFH helper functions (histogram building, gap selection, steering command).",
  "direction": "1. Add a function _vfh_histogram(pose, raw) that converts unmapped lidar points to polar bins (e.g., 5° resolution) and counts obstacles per bin. 2. Add _vfh_select_gap(hist) that finds the widest consecutive sequence of empty bins wider than the robot footprint plus safety margin and returns the central bearing. 3. In controller(), after _perceive() call _unmapped_raw() to get raw points and compute (hist, gap_bearing) via the new helpers. 4. If a gap exists, compute desired heading = yaw + gap_bearing and set w = _clamp(7.5*(desired_heading‑yaw), -_DWA_W_MAX, _DWA_W_MAX). 5. Compute v_nom from _follow() toward the waypoint, then limit v by _lidar_clear and by the distance to the nearest obstacle in that direction (e.g., v = min(v_nom, d_gap‑_R_ROBOT‑0.1)). 6. Run the final command through _guard() and return; otherwise, fall back to the original waypoint follower when no gap is found.",
  "confidence": "medium"
}
